      : `${operation.route.method} ${operation.route.path}`;
  return raw
    .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, ":param")
    .replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, ":param");
