/**
 * Logging middleware.
 */

import type { BrowseFnEvent, EventData } from '../core/types.js';

const SENSITIVE_QUERY_KEYS = new Set([
  'access_token',
  'api_key',
  'apikey',
  'authorization',
  'client_id',
  'key',
  'password',
  'secret',
  'signature',
  'token',
]);

const SENSITIVE_FIELD_NAMES = new Set([
  'authorization',
  'cookie',
  'client_id',
  'api_key',
  'apikey',
  'password',
  'secret',
  'token',
]);

export class Logger {
  private logs: EventData[] = [];

  log(event: BrowseFnEvent, data: Omit<EventData, 'event' | 'timestamp'>): EventData {
    const entry = Logger.sanitizeEventData({
      ...data,
      event,
      timestamp: Date.now(),
    });

    this.logs.push(entry);
    if (this.logs.length > 1000) {
      this.logs.shift();
    }

    return entry;
  }

  getLogs(filter?: { event?: BrowseFnEvent; provider?: string; since?: number }): EventData[] {
    let filtered = [...this.logs];
    const since = filter?.since;

    if (typeof since === 'number') {
      filtered = filtered.filter((log) => log.timestamp >= since);
    }

    if (filter?.event) {
      filtered = filtered.filter((log) => log.event === filter.event);
    }

    if (filter?.provider) {
      filtered = filtered.filter((log) => log.provider === filter.provider);
    }

    return filtered;
  }

  clear(): void {
    this.logs = [];
  }

  count(): number {
    return this.logs.length;
  }

  private static sanitizeEventData(entry: EventData): EventData {
    return {
      ...entry,
      url: entry.url ? Logger.redactUrl(entry.url) : undefined,
      details: entry.details ? (Logger.redactValue(entry.details) as Record<string, unknown>) : undefined,
    };
  }

  private static redactUrl(input: string): string {
    try {
      const url = new URL(input);
      for (const key of url.searchParams.keys()) {
        if (SENSITIVE_QUERY_KEYS.has(key.toLowerCase())) {
          url.searchParams.set(key, '[REDACTED]');
        }
      }
      return url.toString();
    } catch {
      return input;
    }
  }

  private static redactValue(value: unknown): unknown {
    if (Array.isArray(value)) {
      return value.map((item) => Logger.redactValue(item));
    }

    if (!value || typeof value !== 'object') {
      return value;
    }

    const record = value as Record<string, unknown>;
    return Object.fromEntries(
      Object.entries(record).map(([key, rawValue]) => {
        if (SENSITIVE_FIELD_NAMES.has(key.toLowerCase())) {
          return [key, '[REDACTED]'];
        }

        if (typeof rawValue === 'string' && key.toLowerCase() === 'url') {
          return [key, Logger.redactUrl(rawValue)];
        }

        return [key, Logger.redactValue(rawValue)];
      })
    );
  }
}
/**
 * Metrics collection middleware.
 */

import type { Metrics, ProviderMetrics } from '../core/types.js';

interface MetricEntry {
  provider: string;
  success: boolean;
  duration: number;
  timestamp: number;
  cached: boolean;
}

export class MetricsCollector {
  private metrics: MetricEntry[] = [];

  record(input: {
    provider?: string;
    success: boolean;
    duration: number;
    cached?: boolean;
  }): void {
    this.metrics.push({
      provider: input.provider ?? 'unknown',
      success: input.success,
      duration: input.duration,
      timestamp: Date.now(),
      cached: input.cached === true,
    });

    if (this.metrics.length > 10_000) {
      this.metrics.shift();
    }
  }

  getMetrics(options?: {
    timeRange?: 'last-hour' | 'last-24h' | 'last-7d' | 'all';
    groupBy?: 'provider';
  }): Metrics {
    let filtered = [...this.metrics];

    if (options?.timeRange && options.timeRange !== 'all') {
      const now = Date.now();
      let cutoff = 0;

      switch (options.timeRange) {
        case 'last-hour':
          cutoff = now - 3_600_000;
          break;
        case 'last-24h':
          cutoff = now - 86_400_000;
          break;
        case 'last-7d':
          cutoff = now - 604_800_000;
          break;
      }

      filtered = filtered.filter((metric) => metric.timestamp >= cutoff);
    }

    const totalRequests = filtered.length;
    const successCount = filtered.filter((metric) => metric.success).length;
    const totalDuration = filtered.reduce((sum, metric) => sum + metric.duration, 0);
    const cacheHits = filtered.filter((metric) => metric.cached).length;

    const byProvider = new Map<string, ProviderMetrics>();

    for (const metric of filtered) {
      if (!byProvider.has(metric.provider)) {
        byProvider.set(metric.provider, {
          name: metric.provider,
          requests: 0,
          successes: 0,
          failures: 0,
          avgResponseTime: 0,
        });
      }

      const providerMetric = byProvider.get(metric.provider)!;
      providerMetric.requests += 1;
      if (metric.success) {
        providerMetric.successes += 1;
      } else {
        providerMetric.failures += 1;
      }
    }

    for (const [provider, providerMetric] of byProvider) {
      const providerEntries = filtered.filter((metric) => metric.provider === provider);
      const providerDuration = providerEntries.reduce((sum, metric) => sum + metric.duration, 0);
      providerMetric.avgResponseTime =
        providerEntries.length > 0 ? providerDuration / providerEntries.length : 0;
    }

    return {
      totalRequests,
      successRate: totalRequests > 0 ? (successCount / totalRequests) * 100 : 0,
      avgResponseTime: totalRequests > 0 ? totalDuration / totalRequests : 0,
      cacheHitRate: totalRequests > 0 ? (cacheHits / totalRequests) * 100 : 0,
      byProvider: Array.from(byProvider.values()).sort((a, b) =>
        a.name.localeCompare(b.name)
      ),
    };
  }

  clear(): void {
    this.metrics = [];
  }
}
/**
 * Rate limiter wrapper that delegates to the shared middleware package.
 */

import {
  createRateLimiter,
  type RateLimiter as SharedRateLimiter,
} from '@superfunctions/middleware/rate-limit';

import { BrowseFnError } from './errors.js';
import type { RateLimitConfig, RateLimitStatus } from './types.js';

type RateLimitListener = (status: RateLimitStatus) => void;

const UNBOUNDED_STATUS: RateLimitStatus = {
  remaining: Number.POSITIVE_INFINITY,
  resetAt: 0,
  limit: Number.POSITIVE_INFINITY,
  allowed: true,
  retryAfterMs: 0,
};

export class RateLimiter {
  private readonly providerLimiters = new Map<string, SharedRateLimiter>();
  private readonly globalLimiter?: SharedRateLimiter;
  private readonly configs = new Map<string, RateLimitConfig>();
  private readonly listeners = new Set<RateLimitListener>();
  private readonly lastStatus = new Map<string, RateLimitStatus>();

  constructor(
    private readonly globalConfig?: RateLimitConfig,
    perProviderConfigs?: Record<string, RateLimitConfig>
  ) {
    if (perProviderConfigs) {
      Object.entries(perProviderConfigs).forEach(([provider, config]) => {
        this.configs.set(provider, config);
        this.providerLimiters.set(
          provider,
          this.createSharedLimiter(config, `browsefn:${provider}:`)
        );
      });
    }

    if (globalConfig) {
      this.globalLimiter = this.createSharedLimiter(globalConfig, 'browsefn:global:');
    }
  }

  getImportPath(): string {
    return '@superfunctions/middleware/rate-limit';
  }

  onRateLimited(listener: RateLimitListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  async check(provider: string): Promise<RateLimitStatus> {
    const config = this.configs.get(provider) ?? this.globalConfig;
    if (!config) {
      return { ...UNBOUNDED_STATUS, provider };
    }

    const limiter = this.getLimiter(provider, config);
    const result = await limiter.check({ key: provider });

    const resetAt = new Date(result.resetAt).getTime();
    const status: RateLimitStatus = {
      allowed: result.allowed,
      remaining: result.remaining,
      resetAt,
      limit: result.total,
      provider,
      retryAfterMs: Math.max(0, resetAt - Date.now()),
    };

    this.lastStatus.set(provider, status);

    if (!result.allowed) {
      this.listeners.forEach((listener) => listener(status));
    }

    return status;
  }

  async checkLimit(provider: string): Promise<boolean> {
    const status = await this.check(provider);
    return status.allowed !== false;
  }

  async waitForLimit(provider: string): Promise<void> {
    const config = this.configs.get(provider) ?? this.globalConfig;
    if (!config) {
      return;
    }

    for (;;) {
      const status = await this.check(provider);
      if (status.allowed !== false) {
        return;
      }

      const delayMs = Math.max(25, status.retryAfterMs ?? status.resetAt - Date.now());
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
  }

  getStatus(provider: string): RateLimitStatus {
    const config = this.configs.get(provider) ?? this.globalConfig;
    if (!config) {
      return { ...UNBOUNDED_STATUS, provider };
    }

    const lastKnown = this.lastStatus.get(provider);
    if (!lastKnown) {
      return {
        remaining: config.requests,
        resetAt: Date.now() + config.window,
        limit: config.requests,
        allowed: true,
        provider,
        retryAfterMs: config.window,
      };
    }

    if (Date.now() >= lastKnown.resetAt) {
      return {
        remaining: config.requests,
        resetAt: Date.now() + config.window,
        limit: config.requests,
        allowed: true,
        provider,
        retryAfterMs: config.window,
      };
    }

    return lastKnown;
  }

  async consume(provider: string): Promise<void> {
    const status = await this.check(provider);
    if (status.allowed === false) {
      throw new BrowseFnError({
        code: 'RATE_LIMITED',
        message: `Rate limit exceeded for provider ${provider}.`,
        provider,
        retryAfterMs: status.retryAfterMs,
      });
    }
  }

  async reset(provider?: string): Promise<void> {
    if (provider) {
      const config = this.configs.get(provider) ?? this.globalConfig;
      if (config) {
        await this.getLimiter(provider, config).reset(provider);
      }
      this.lastStatus.delete(provider);
      return;
    }

    const providers = new Set<string>([
      ...this.configs.keys(),
      ...this.lastStatus.keys(),
    ]);

    await Promise.all(
      Array.from(providers).map(async (name) => {
        const config = this.configs.get(name) ?? this.globalConfig;
        if (config) {
          await this.getLimiter(name, config).reset(name);
        }
        this.lastStatus.delete(name);
      })
    );
  }

  setConfig(provider: string, config: RateLimitConfig): void {
    this.configs.set(provider, config);
    this.providerLimiters.set(
      provider,
      this.createSharedLimiter(config, `browsefn:${provider}:`)
    );
    this.lastStatus.delete(provider);
  }

  private getLimiter(provider: string, config: RateLimitConfig): SharedRateLimiter {
    return (
      this.providerLimiters.get(provider) ??
      this.globalLimiter ??
      this.createSharedLimiter(config, `browsefn:${provider}:`)
    );
  }

  private createSharedLimiter(
    config: RateLimitConfig,
    keyPrefix: string
  ): SharedRateLimiter {
    return createRateLimiter({
      windowMs: config.window,
      maxRequests: config.requests,
      keyPrefix,
    });
  }
}
