import {
  createCapabilityAdminClient,
  type AdminClient,
  type AdminClientRequestOptions,
} from "@superfunctions/admin";
import { browseFnAdminCapability } from "./capability.js";
import type {
  BrowseFnClearInput,
  BrowseFnGetMetricsInput,
  BrowseFnGetRateLimitInput,
  BrowseFnListLogsInput,
} from "./types.js";

/** Function-scoped TypeScript client with named methods for every BrowseFn operation. */
export function createBrowseFnAdminClient(adminClient: AdminClient) {
  const client = createCapabilityAdminClient(browseFnAdminCapability, adminClient);
  return Object.assign(client, {
    providers: {
      list: (options?: AdminClientRequestOptions) => client.invoke("browsefn.providers.list", {}, options),
    },
    metrics: {
      get: (input: BrowseFnGetMetricsInput = {}, options?: AdminClientRequestOptions) => client.invoke("browsefn.metrics.get", input, options),
      clear: (input: BrowseFnClearInput, options?: AdminClientRequestOptions) => client.invoke("browsefn.metrics.clear", input, options),
    },
    rateLimits: {
      get: (input: BrowseFnGetRateLimitInput, options?: AdminClientRequestOptions) => client.invoke("browsefn.rate-limits.get", input, options),
    },
    logs: {
      list: (input: BrowseFnListLogsInput = {}, options?: AdminClientRequestOptions) => client.invoke("browsefn.logs.list", input, options),
      clear: (input: BrowseFnClearInput, options?: AdminClientRequestOptions) => client.invoke("browsefn.logs.clear", input, options),
    },
    cache: {
      get: (options?: AdminClientRequestOptions) => client.invoke("browsefn.cache.get", {}, options),
      clear: (input: BrowseFnClearInput, options?: AdminClientRequestOptions) => client.invoke("browsefn.cache.clear", input, options),
    },
  });
}

import {
  createAdminCapabilityAdapter as createKernelAdminCapabilityAdapter,
  type AdminCapabilityAdapter,
  type AdminOperationContext,
  type AdminOperationRequest,
} from "@superfunctions/admin";
import { browseFnAdminCapability } from "./capability.js";
import type { BrowseFnAdminService } from "./types.js";

function bind<TInput, TOutput>(
  handler: (input: TInput, context: AdminOperationContext) => Promise<TOutput>,
) {
  return ({ input, context }: AdminOperationRequest) => handler(input as TInput, context);
}

/** Maps every manifest operation to one explicit, typed BrowseFn admin method. */
export function createBrowseFnAdminAdapter(
  service: BrowseFnAdminService,
): AdminCapabilityAdapter<typeof browseFnAdminCapability> {
  return createKernelAdminCapabilityAdapter(browseFnAdminCapability, {
    "browsefn.providers.list": bind(service.listProviders),
    "browsefn.metrics.get": bind(service.getMetrics),
    "browsefn.metrics.clear": bind(service.clearMetrics),
    "browsefn.rate-limits.get": bind(service.getRateLimit),
    "browsefn.logs.list": bind(service.listLogs),
    "browsefn.logs.clear": bind(service.clearLogs),
    "browsefn.cache.get": bind(service.getCache),
    "browsefn.cache.clear": bind(service.clearCache),
  });
}

export const createAdminAdapter = createBrowseFnAdminAdapter;

