          size: stats?.size ?? null,
        },
      };
    },

    async clearCache(_input: BrowseFnClearCacheInput, context): Promise<BrowseFnAcceptedOutput> {
      assertScope(context);
      requireIdempotency(context);
      await options.browsefn.clearCache();
